	private static int? ResolveInitialCatalogNextPage(StorePageData pageData, int renderedCatalogCount)
	{
		if (pageData.Games.Count > renderedCatalogCount)
		{
			return 2;
		}
		if (pageData.CatalogNextPage.HasValue)
		{
			return pageData.CatalogNextPage;
		}
		if (pageData.Games.Count <= renderedCatalogCount)
		{
			return null;
		}
		return 2;
	}

	private static IReadOnlyList<string> BuildGenreTags(StorePageData pageData, IReadOnlyList<string> categories)
	{
		List<string> list = (from item in pageData.Games.SelectMany((StoreGame game) => game.Genres.Prepend(game.Category)).Concat(pageData.CatalogGenres).Concat(categories)
			where !IsAllCategoryLabel(item)
			where !string.IsNullOrWhiteSpace(item)
			select item.Trim()).Distinct<string>(StringComparer.OrdinalIgnoreCase).ToList();
		string[] defaultGenreTags = DefaultGenreTags;
		foreach (string text in defaultGenreTags)
		{
			if (!list.Contains<string>(text, StringComparer.OrdinalIgnoreCase))
			{
				list.Add(text);
			}
		}
		return list.Take(32).ToArray();
	}

	private static bool IsAllCategoryLabel(string? value)
	{
		if (string.IsNullOrWhiteSpace(value))
		{
			return true;
		}
		string text = value.Trim();
		if (!text.Equals("Tat ca", StringComparison.OrdinalIgnoreCase) && !text.Equals("Tat ca game", StringComparison.OrdinalIgnoreCase) && !text.Equals("Tất cả", StringComparison.OrdinalIgnoreCase))
		{
			return text.Equals("Tất cả game", StringComparison.OrdinalIgnoreCase);
		}
		return true;
	}

	private static string RenderGenreDropdown(IReadOnlyList<string> tags)
	{
		StringBuilder stringBuilder = new StringBuilder();
		foreach (string tag in tags)
		{
			StringBuilder stringBuilder2 = stringBuilder;
			StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(73, 2, stringBuilder2);
			handler.AppendLiteral("<button type=\"button\" class=\"genre-option\" data-genre-filter=\"");
			handler.AppendFormatted(Attr(tag));
			handler.AppendLiteral("\">");
			handler.AppendFormatted(Html(tag));
			handler.AppendLiteral("</button>");
			stringBuilder2.Append(ref handler);
		}
		return $"<div class=\"filter-dropdown genre-dropdown\" data-filter-panel=\"genres\" hidden>\r\n    <label class=\"genre-search\">\r\n        <input type=\"search\" placeholder=\"Tìm tags...\" data-tag-search />\r\n    </label>\r\n    <div class=\"genre-grid\">\r\n        <button type=\"button\" class=\"genre-option is-selected\" data-genre-filter=\"all\">Tất cả</button>\r\n        {stringBuilder}\r\n    </div>\r\n</div>";
	}

	private static string RenderCategoryDropdown(IReadOnlyList<string> categories)
	{
		StringBuilder stringBuilder = new StringBuilder();
		foreach (string item in categories.Where((string item) => !IsAllCategoryLabel(item)))
		{
			StringBuilder stringBuilder2 = stringBuilder;
			StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(76, 2, stringBuilder2);
			handler.AppendLiteral("<button type=\"button\" class=\"genre-option\" data-category-filter=\"");
			handler.AppendFormatted(Attr(item));
			handler.AppendLiteral("\">");
			handler.AppendFormatted(Html(item));
			handler.AppendLiteral("</button>");
			stringBuilder2.Append(ref handler);
		}
		return $"<div class=\"filter-dropdown category-dropdown\" data-filter-panel=\"categories\" hidden>\r\n    <label class=\"genre-search\">\r\n        <input type=\"search\" placeholder=\"Tìm danh mục...\" data-category-search />\r\n    </label>\r\n    <div class=\"genre-grid category-grid\">\r\n        <button type=\"button\" class=\"genre-option is-selected\" data-category-filter=\"all\">Tất cả</button>\r\n        {stringBuilder}\r\n    </div>\r\n</div>";
	}

	private static string RenderHeroBanner(StorePageData pageData)
	{
		Dictionary<int, StoreHeroBannerSlot> dictionary = (from item in pageData.HeroBannerSlots.Select((StoreHeroBannerSlot slot) => new
			{
				Slot = slot,
				TileNumber = TryGetHeroTileNumber(slot.CssClass)
			}).Where(item =>
			{
				switch (item.TileNumber)
				{
				case 1:
				case 2:
				case 3:
				case 4:
				case 5:
				case 6:
				case 7:
				case 8:
					return !string.IsNullOrWhiteSpace(item.Slot.ImageUrl);
				default:
					return false;
				}
			})
			group item by item.TileNumber.Value).ToDictionary(group => group.Key, group => (from item in @group
			orderby item.Slot.DisplayOrder
			select item.Slot).First());
		if (dictionary.Count == 0)
		{
			return string.Empty;
		}
		StringBuilder stringBuilder = new StringBuilder();
		for (int i = 1; i <= 8; i++)
		{
			if (dictionary.TryGetValue(i, out var value))
			{
				stringBuilder.Append(RenderHeroTile(i, value.ImageUrl, value.AltText, value.CropFocusX, value.CropFocusY));
			}
		}
		return $"<section class=\"hero-banner\" data-hero-banner aria-label=\"NestG\">\r\n    <div class=\"hero-brand-panel\">\r\n        <span class=\"hero-kicker\">NESTG LAUNCHER</span>\r\n        <h1>NestG</h1>\r\n    </div>\r\n    <div class=\"hero-collage\">\r\n        {stringBuilder}\r\n    </div>\r\n</section>";
	}

	private static string RenderHeroTile(int tileNumber, string imageUrl, string? altText, decimal cropFocusX, decimal cropFocusY)
	{
		string value = Math.Clamp(cropFocusX, 0m, 100m).ToString("0.##", CultureInfo.InvariantCulture);
		string value2 = Math.Clamp(cropFocusY, 0m, 100m).ToString("0.##", CultureInfo.InvariantCulture);
		string value3 = (string.IsNullOrWhiteSpace(altText) ? $"NestG artwork {tileNumber}" : altText.Trim());
		return $"<div class=\"hero-tile tile-{tileNumber}\">\r\n    <img src=\"{Attr(imageUrl)}\" alt=\"{Attr(value3)}\" loading=\"eager\" data-hero-tile-image style=\"object-position: {value}% {value2}%;\" />\r\n</div>";
	}

	private static int? TryGetHeroTileNumber(string? cssClass)
	{
		if (string.IsNullOrWhiteSpace(cssClass))
		{
			return null;
		}
		string text = cssClass.Trim();
		if (!text.StartsWith("tile-", StringComparison.OrdinalIgnoreCase) || !int.TryParse(text.Substring("tile-".Length), NumberStyles.Integer, CultureInfo.InvariantCulture, out var result) || result < 1 || result > 8)
		{
			return null;
		}
		return result;
	}

