	private static string RenderSaleCountdown(StoreSaleGame sale)
	{
		if (!sale.SaleEndsAt.HasValue)
		{
			return string.Empty;
		}
		DateTime dateTime = NormalizeUtc(sale.SaleEndsAt.Value);
		string value = new DateTimeOffset(dateTime).ToUnixTimeMilliseconds().ToString(CultureInfo.InvariantCulture);
		return $"<div class=\"countdown sale-countdown\" data-countdown=\"{value}\">{Html(BuildCountdownText(dateTime))}</div>";
	}

	private static string BuildCountdownText(DateTime utcTarget)
	{
		TimeSpan timeSpan = utcTarget - DateTime.UtcNow;
		if (timeSpan < TimeSpan.Zero)
		{
			timeSpan = TimeSpan.Zero;
		}
		return $"{(int)Math.Floor(timeSpan.TotalDays)} ngày {timeSpan.Hours:00}:{timeSpan.Minutes:00}:{timeSpan.Seconds:00}";
	}

	private static DateTime NormalizeUtc(DateTime value)
	{
		return value.Kind switch
		{
			DateTimeKind.Utc => value, 
			DateTimeKind.Local => value.ToUniversalTime(), 
			_ => DateTime.SpecifyKind(value, DateTimeKind.Utc), 
		};
	}

