	private static string RenderImage(string? imageUrl, string alt)
	{
		if (string.IsNullOrWhiteSpace(imageUrl))
		{
			return "<div class=\"image-fallback\">" + Html(alt) + "</div>";
		}
		return $"<img src=\"{Attr(imageUrl)}\" alt=\"{Attr(alt)}\" loading=\"lazy\" />";
	}

	private static string RenderSaleImage(StoreSaleGame sale)
	{
		string text = ResolveSaleImageUrl(sale);
		if (string.IsNullOrWhiteSpace(text))
		{
			return "<div class=\"image-fallback\">" + Html(sale.Title) + "</div>";
		}
		string value = ((!string.IsNullOrWhiteSpace(sale.PosterImageUrl) && !string.Equals(text, sale.PosterImageUrl, StringComparison.OrdinalIgnoreCase)) ? (" data-fallback-src=\"" + Attr(sale.PosterImageUrl) + "\" ") : string.Empty);
		return $"<img src=\"{Attr(text)}\"{value} alt=\"{Attr(sale.Title)}\" loading=\"lazy\" />";
	}

	private static string RenderDiscount(string? value)
	{
		if (!string.IsNullOrWhiteSpace(value))
		{
			return "<span class=\"discount-flag\">" + Html(value) + "</span>";
		}
		return string.Empty;
	}

	private static string RenderStrike(string? value)
	{
		if (!string.IsNullOrWhiteSpace(value))
		{
			return "<s>" + Html(value) + "</s>";
		}
		return string.Empty;
	}

	private static string ResolveImageUrl(StoreGame game)
	{
		string? text;
		if (string.IsNullOrWhiteSpace(game.PosterImageUrl))
		{
			text = game.SpotlightImageUrl;
			if (text == null)
			{
				return string.Empty;
			}
		}
		else
		{
			text = game.PosterImageUrl;
		}
		return text;
	}

	private static string ResolveSaleImageUrl(StoreSaleGame sale)
	{
		string? text;
		if (string.IsNullOrWhiteSpace(sale.PortraitImageUrl))
		{
			text = sale.PosterImageUrl;
			if (text == null)
			{
				return string.Empty;
			}
		}
		else
		{
			text = sale.PortraitImageUrl;
		}
		return text;
	}

	private static string BuildSearchIndex(StoreGame game)
	{
		return $"{game.Title} {game.Subtitle} {game.Category} {game.BadgeText} {string.Join(' ', game.Genres)}";
	}

	private static string BuildTagIndex(StoreGame game)
	{
		return string.Join('|', (from item in game.Genres.Prepend(game.Category)
			where !string.IsNullOrWhiteSpace(item)
			select item.Trim()).Distinct<string>(StringComparer.OrdinalIgnoreCase));
	}

	private static string Html(string? value)
	{
		return WebUtility.HtmlEncode(value ?? string.Empty);
	}

	private static string Attr(string? value)
	{
		return WebUtility.HtmlEncode(value ?? string.Empty);
	}

