                     <dt>Nội dung</dt><dd data-order-checkout-content></dd>\r\n                        <dt>Hết hạn</dt><dd data-order-checkout-expires></dd>\r\n                    </dl>\r\n                </section>\r\n                <section>\r\n                    <h3>Sản phẩm</h3>\r\n                    <div class=\"order-checkout-items\" data-order-checkout-items></div>\r\n                </section>\r\n                <div class=\"order-checkout-actions\">\r\n                    <button type=\"button\" data-order-checkout-wallet>Thanh toán bằng ví</button>\r\n                    <button type=\"button\" data-order-checkout-refresh>Làm mới trạng thái</button>\r\n                    <button type=\"button\" data-order-checkout-confirm hidden>Đã hiểu</button>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </section>\r\n</div>";
	}

	internal static string BuildLoadingOverlay()
