s></p>\r\n        <footer class=\"launcher-update-actions\">\r\n            <button type=\"button\" class=\"launcher-update-secondary\" data-launcher-update-dismiss>Để sau</button>\r\n            <button type=\"button\" class=\"launcher-update-danger\" data-launcher-update-exit hidden>Thoát</button>\r\n            <button type=\"button\" class=\"launcher-update-primary\" data-launcher-update-start>Cập nhật ngay</button>\r\n        </footer>\r\n    </section>\r\n</div>";
