	internal static string BuildStyles()
	{
		return ":root {\r\n    color-scheme: dark;\r\n    --bg: #070d14;\r\n    --bg-2: #0a111b;\r\n    --bar: #080c12;\r\n    --bar-2: #101823;\r\n    --line: #203044;\r\n    --line-soft: rgba(83, 117, 155, .34);\r\n    --text: #f2f7ff;\r\n    --muted: #8fa0b6;\r\n    --soft: #c5d1df;\r\n    --cyan: #27d9ff;\r\n    --blue: #289bed;\r\n    --gold: #ffd26a;\r\n    --panel: #101a26;\r\n    --panel-2: #0c151f;\r\n    --shadow: 0 18px 44px rgba(0,0,0,.38);\r\n}\r\n* { box-sizing: border-box; }\r\nhtml, body { min-height: 100%; margin: 0; }\r\nbody {\r\n    background:\r\n        radial-gradient(circle at 50% -20%, rgba(39, 120, 170, .18), transparent 34%),\r\n        linear-gradient(180deg, #0b121b 0, #060b11 100%);\r\n    color: var(--text);\r\n    font-family: \"Segoe UI Variable Text\", \"Segoe UI\", Arial, sans-serif;\r\n    overflow-x: hidden;\r\n}\r\nbutton, input { font: inherit; }\r\nbutton { color: inherit; }\r\nbutton, [data-host-action] { cursor: pointer; }\r\n[hidden] { display: none !important; }\r\nimg { display: block; width: 100%; height: 100%; object-fit: cover; user-select: none; -webkit-user-drag: none; }\r\nbody::-webkit-scrollbar { width: 10px; height: 10px; }\r\nbody::-webkit-scrollbar-track { background: rgba(8, 13, 20, .65); }\r\nbody::-webkit-scrollbar-thumb {\r\n    background: rgba(61, 106, 145, .86);\r\n    border-radius: 999px;\r\n    border: 2px solid rgba(8, 13, 20, .65);\r\n}\r\n.horizontal-rail {\r\n    scrollbar-width: none;\r\n    -ms-overflow-style: none;\r\n}\r\n.horizontal-rail::-webkit-scrollbar {\r\n    display: none;\r\n    width: 0;\r\n    height: 0;\r\n}\r\n.app-shell { min-height: 100vh; padding-bottom: 48px; }\r\n.top-chrome {\r\n    position: sticky;\r\n    top: 0;\r\n    z-index: 200;\r\n    background: linear-gradient(180deg, rgba(9, 13, 19, .98), rgba(8, 13, 20, .94));\r\n    border-bottom: 1px solid rgba(75, 95, 120, .22);\r\n    box-shadow: 0 12px 32px rgba(0,0,0,.36);\r\n}\r\n.utility-row, .main-row, .filter-bar {\r\n    display: grid;\r\n    align-items: center;\r\n    gap: clamp(10px, 1.1vw, 18px);\r\n    padding-inline: clamp(14px, 1.25vw, 22px);\r\n}\r\n.utility-row {\r\n    position: relative;\r\n    z-index: 2;\r\n    grid-template-columns: minmax(0, 1fr) auto;\r\n    height: 46px;\r\n}\r\n.utility-left, .utility-right, .primary-nav, .account-cluster, .window-controls, .filter-group, .rail-actions, .price-line, .catalog-actions {\r\n    display: flex;\r\n    align-items: center;\r\n}\r\n.utility-left { gap: clamp(8px, .75vw, 12px); min-width: 0; color: var(--muted); font-size: clamp(11px, .78vw, 13px); }\r\n.utility-right { justify-self: end; gap: clamp(8px, .85vw, 14px); min-width: 0; }\r\n.window-controls { gap: clamp(5px, .5vw, 8px); flex-shrink: 0; }\r\n.top-chrome button:focus-visible { outline: 2px solid #66c0f4; outline-offset: -2px; }\r\n.brand-word {\r\n    min-width: 0;\r\n    display: inline-flex;\r\n    align-items: center;\r\n    gap: 10px;\r\n    padding: 0;\r\n    border: 0;\r\n    background: transparent;\r\n    color: #f5f8fc;\r\n}\r\n.brand-word img {\r\n    width: 32px;\r\n    height: 36px;\r\n    object-fit: contain;\r\n    flex: 0 0 auto;\r\n}\r\n.brand-word strong {\r\n    font-size: 18px;\r\n    font-weight: 900;\r\n    letter-spacing: .02em;\r\n}\r\n.utility-link, .vip-link, .voice-link, .window-button, .nav-item, .wishlist-button, .cart-pill, .user-chip, .filter-button, .filter-chip, .rail-button, .mini-cart, .bottom-bar button, .primary-command {\r\n    border: 0;\r\n    background: transparent;\r\n    white-space: nowrap;\r\n}\r\n.vip-link { color: var(--gold); font-size: clamp(11px, .78vw, 13px); font-weight: 800; letter-spacing: .04em; text-shadow: 0 0 12px rgba(255, 210, 106, .28); }\r\n.voice-link { color: #cc7dff; font-size: clamp(11px, .78vw, 13px); font-weight: 800; letter-spacing: .08em; text-shadow: 0 0 12px rgba(204, 125, 255, .45); }\r\n.divider { width: 1px; height: 22px; background: #1d2634; }\r\n.window-button {\r\n    width: clamp(30px, 2vw, 36px);\r\n    height: 28px;\r\n    color: #d6deeb;\r\n    border-radius: 4px;\r\n    font-size: 13px;\r\n}\r\n.window-button:hover { background: rgba(255,255,255,.08); }\r\n.window-button.is-close:hover { background: #c83232; color: #fff; }\r\n.main-row {\r\n    position: relative;\r\n    z-index: 1;\r\n    grid-template-columns: minmax(0, 1fr) minmax(320px, 532px);\r\n    height: 58px;\r\n}\r\n.primary-nav { gap: clamp(18px, 1.7vw, 29px); min-width: 0; }\r\n.nav-item {\r\n    position: relative;\r\n    height: 38px;\r\n    padding: 0;\r\n    color: #f0f6ff;\r\n    font-size: clamp(13px, .95vw, 16px);\r\n    font-weight: 800;\r\n    letter-spacing: .08em;\r\n}\r\n.nav-item--event {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    gap: 7px;\r\n}\r\n.nav-new-badge {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    min-width: 31px;\r\n    height: 19px;\r\n    padding: 0 6px;\r\n    border: 1px solid rgba(255, 128, 140, .3);\r\n    border-radius: 5px;\r\n    background: linear-gradient(180deg, #e64b5d 0%, #c92e42 100%);\r\n    box-shadow: 0 3px 10px rgba(204, 43, 64, .32), inset 0 1px 0 rgba(255, 255, 255, .16);\r\n    color: #fff;\r\n    font-size: 10px;\r\n    font-weight: 900;\r\n    line-height: 1;\r\n    letter-spacing: .025em;\r\n    transform: translateY(-7px);\r\n}\r\n.nav-item.is-muted { color: #7e839e; }\r\n.nav-item.is-active::after {\r\n    content: \"\";\r\n    position: absolute;\r\n    left: 0;\r\n    right: 0;\r\n    bottom: 0;\r\n    height: 3px;\r\n    background: var(--cyan);\r\n    box-shadow: 0 0 18px rgba(39, 217, 255, .55);\r\n}\r\n.account-cluster { gap: clamp(6px, .7vw, 10px); min-width: 0; }\r\n.wishlist-button {\r\n    max-width: clamp(118px, 10vw, 154px);\r\n    overflow: hidden;\r\n    text-overflow: ellipsis;\r\n    color: #fff;\r\n    font-size: clamp(11px, .82vw, 14px);\r\n    font-weight: 700;\r\n}\r\n.cart-pill {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    gap: 8px;\r\n    min-width: clamp(126px, 9.8vw, 154px);\r\n    height: 36px;\r\n    padding: 0 clamp(10px, .85vw, 13px);\r\n    border-radius: 999px;\r\n    background: linear-gradient(135deg, #1a91ed, #34b6ff);\r\n    color: #fff;\r\n    font-size: clamp(11px, .82vw, 13px);\r\n    font-weight: 850;\r\n    box-shadow:\r\n        0 10px 24px rgba(20, 148, 235, .22),\r\n        inset 0 1px rgba(255,255,255,.18);\r\n}\r\n.cart-icon {\r\n    width: 22px;\r\n    height: 22px;\r\n    display: inline-grid;\r\n    place-items: center;\r\n    border-radius: 999px;\r\n    background: rgba(255,255,255,.13);\r\n    font-size: 12px;\r\n    flex: 0 0 auto;\r\n}\r\n.cart-label {\r\n    min-width: 0;\r\n    overflow: hidden;\r\n    text-overflow: ellipsis;\r\n    white-space: nowrap;\r\n}\r\n.cart-pill strong {\r\n    min-width: 22px;\r\n    height: 22px;\r\n    padding: 0 6px;\r\n    display: inline-grid;\r\n    place-items: center;\r\n    border-radius: 999px;\r\n    background: rgba(255,255,255,.2);\r\n    color: #f4fbff;\r\n    font-size: 12px;\r\n    line-height: 1;\r\n    flex: 0 0 auto;\r\n}\r\n.user-chip {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    gap: 7px;\r\n    height: 36px;\r\n    padding: 0 clamp(8px, .65vw, 10px) 0 8px;\r\n    border: 1px solid #2b5c82;\r\n    border-radius: 5px;\r\n    background: #173652;\r\n    color: #9ed6ff;\r\n    font-size: clamp(11px, .82vw, 13px);\r\n    transition: border-color .16s ease, background .16s ease, box-shadow .16s ease;\r\n}\r\n.user-chip:hover,\r\n.user-chip:focus-visible,\r\n.user-chip.is-open {\r\n    border-color: rgba(112, 199, 255, .72);\r\n    background: #1d4567;\r\n    box-shadow: 0 0 0 2px rgba(102, 192, 244, .08);\r\n    outline: none;\r\n}\r\n.user-chip strong { color: #e8f4ff; font-weight: 500; }\r\n.user-chip > span:nth-child(2) {\r\n    max-width: clamp(82px, 8vw, 138px);\r\n    overflow: hidden;\r\n    text-overflow: ellipsis;\r\n}\r\n.avatar-box {\r\n    width: 26px;\r\n    height: 26px;\r\n    display: inline-grid;\r\n    place-items: center;\r\n    border: 2px solid #70c7ff;\r\n    border-radius: 3px;\r\n    color: #8ed4ff;\r\n    font-size: 13px;\r\n    font-weight: 900;\r\n}\r\n.account-menu-shell {\r\n    position: relative;\r\n    z-index: 210;\r\n    flex: 0 0 auto;\r\n}\r\n.account-menu {\r\n    position: absolute;\r\n    top: calc(100% + 9px);\r\n    right: 0;\r\n    z-index: 120;\r\n    width: 286px;\r\n    max-width: calc(100vw - 24px);\r\n    max-height: calc(100dvh - 80px);\r\n    overflow-y: auto;\r\n    border: 1px solid rgba(83, 139, 180, .48);\r\n    border-radius: 5px;\r\n    background: linear-gradient(180deg, rgba(18, 38, 53, .99), rgba(8, 21, 31, .99));\r\n    box-shadow:\r\n        0 24px 55px rgba(0, 0, 0, .52),\r\n        inset 0 1px rgba(255, 255, 255, .04);\r\n    animation: account-menu-in .14s ease-out both;\r\n}\r\n.account-menu::before {\r\n    content: \"\";\r\n    position: absolute;\r\n    top: 0;\r\n    right: 18px;\r\n    width: 54px;\r\n    height: 2px;\r\n    background: #66c0f4;\r\n    box-shadow: 0 0 12px rgba(102, 192, 244, .42);\r\n}\r\n.account-menu-summary {\r\n    display: grid;\r\n    grid-template-columns: 42px minmax(0, 1fr);\r\n    gap: 12px;\r\n    align-items: center;\r\n    padding: 16px;\r\n    border-bottom: 1px solid rgba(102, 192, 244, .1);\r\n    background: rgba(27, 59, 80, .36);\r\n}\r\n.account-menu-avatar {\r\n    width: 42px;\r\n    height: 42px;\r\n    display: grid;\r\n    place-items: center;\r\n    border: 1px solid rgba(112, 199, 255, .6);\r\n    border-radius: 4px;\r\n    background: #173652;\r\n    color: #9be5ff;\r\n    font-size: 17px;\r\n    font-weight: 950;\r\n}\r\n.account-menu-summary > span:last-child {\r\n    min-width: 0;\r\n    display: grid;\r\n    gap: 4px;\r\n}\r\n.account-menu-summary strong {\r\n    overflow: hidden;\r\n    color: #f3f8fc;\r\n    font-size: 13px;\r\n    font-weight: 850;\r\n    text-overflow: ellipsis;\r\n    white-s