() => focusManagedModals.find(element => !element.hidden) || null;\r\n    const getModalFocusables = modal => Array.from(modal?.querySelectorAll(\r\n        'button:not(:disabled), a[href], input:not(:disabled), select:not(:disabled), textarea:not(:disabled), [tabindex]:not([tabindex=\"-1\"])') || [])\r\n        .filter(element => !element.hidden);\r\n    focusManagedModals.forEach(modal => {\r\n        new MutationObserver(() => {\r\n            if (!modal.hidden) {\r\n                lastModalFocusedElement = document.activeElement instanceof HTMLElement\r\n                    ? document.activeElement\r\n                    : null;\r\n                window.setTimeout(() => {\r\n                    const focusables = getModalFocusables(modal);\r\n                    (focusables[0] || modal.querySelector('[role=\"dialog\"]') || modal)?.focus?.();\r\n                }, 0);\r\n            } else {\r\n                lastModalFocusedElement?.focus?.();\r\n            }\r\n        }).observe(modal, { attributes: true, attributeFilter: ['hidden'] });\r\n    });\r\n    const renderedCatalogIds = new Set(\r\n        Array.from(document.querySelectorAll('[data-card][data-game-id]'))\r\n            .map(card => card.getAttribute('data-game-id'))\r\n            .filter(Boolean)\r\n    );\r\n    let lastOpenedGameId = '';\r\n    const currencyFormatter = new Intl.NumberFormat('vi-VN', {\r\n        style: 'currency',\r\n        currency: 'VND',\r\n        maximumFractionDigits: 0\r\n    });\r\n\r\n    function showToast(message) {\r\n        if (!toastHost || !message) {\r\n            return;\r\n        }\r\n\r\n        const toast = document.createElement('div');\r\n        toast.className = 'toast';\r\n        toast.textContent = message;\r\n        toastHost.append(toast);\r\n        window.setTimeout(() => toast.remove(), 3400);\r\n    }\r\n\r\n    function setSupportStatus(message, isError = false) {\r\n        if (!supportStatus) return;\r\n        supportStatus.textContent = normalizeSupportStatusText(message);\r\n        supportStatus.style.color = isError ? '#fecaca' : '#9eb4c9';\r\n    }\r\n\r\n    function normalizeSupportStatusText(message) {\r\n        if (!message) return '';\r\n        const normalized = String(message).trim();\r\n        const lower = normalized.toLowerCase();\r\n        const statusMap = {\r\n            open: 'Đang mở',\r\n            pending_user: 'Đang chờ bạn phản hồi',\r\n            pending_admin: 'Đang chờ admin phản hồi',\r\n            'waiting for user': 'Đang chờ bạn phản hồi',\r\n            'waiting for admin': 'Đang chờ admin phản hồi',\r\n            resolved: 'Đã xử lý',\r\n            closed: 'Đã đóng',\r\n            unknown: 'Chưa xác định',\r\n            'dang ket noi...': 'Đang kết nối...',\r\n            'dang online': 'Đang trực tuyến',\r\n            'da gui': 'Đã gửi',\r\n            'khong the gui tin nhan': 'Không thể gửi tin nhắn',\r\n            'khong the ket noi ho tro': 'Không thể kết nối hỗ trợ'\r\n        };\r\n\r\n        return statusMap[lower] || normalized;\r\n    }\r\n\r\n    function setSupportBadge(count) {\r\n        supportUnreadCount = Math.max(0, Number(count) || 0);\r\n        if (!supportBadge) return;\r\n        supportBadge.hidden = supportUnreadCount <= 0;\r\n        supportBadge.textContent = String(supportUnreadCount);\r\n    }\r\n\r\n    function scrollSupportToBottom() {\r\n        if (supportMessages) {\r\n            supportMessages.scrollTop = supportMessages.scrollHeight;\r\n        }\r\n    }\r\n\r\n    function setSupportEmptyVisible(isVisible) {\r\n        if (supportEmpty) {\r\n            supportEmpty.hidden = !isVisible;\r\n        }\r\n    }\r\n\r\n    function createSupportClientId() {\r\n        if (window.crypto?.randomUUID) {\r\n            return window.crypto.randomUUID();\r\n        }\r\n        return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, character => {\r\n            const value = Math.random() * 16 | 0;\r\n            const resolved = character === 'x' ? value : (value & 0x3 | 0x8);\r\n            return resolved.toString(16);\r\n        });\r\n    }\r\n\r\n    function renderSupportMessage(message, options = {}) {\r\n        if (!supportMessages || !message) return null;\r\n        const messageId = message.messageId || '';\r\n        const clientMessageId = message.clientMessageId || options.clientMessageId || '';\r\n        if (messageId && supportMessages.querySelector(`[data-message-id=\"${messageId}\"]`)) {\r\n            return null;\r\n        }\r\n        if (clientMessageId && supportMessages.querySelector(`[data-client-message-id=\"${clientMessageId}\"]:not(.is-pending)`)) {\r\n            return null;\r\n        }\r\n\r\n        const pendingNode = clientMessageId\r\n            ? supportMessages.querySelector(`[data-client-message-id=\"${clientMessageId}\"].is-pending`)\r\n            : null;\r\n        const node = pendingNode || document.createElement('article');\r\n        node.className = 'support-message';\r\n        node.classList.toggle('is-user', (message.senderRole || options.senderRole) !== 'admin');\r\n        node.classList.toggle('is-admin', (message.senderRole || options.senderRole) === 'admin');\r\n        node.classList.toggle('is-pending', Boolean(options.pending));\r\n        node.classList.toggle('is-error', Boolean(options.error));\r\n        if (messageId) node.dataset.messageId = messageId;\r\n        if (clientMessageId) node.dataset.clientMessageId = clientMessageId;\r\n        node.textContent = '';\r\n\r\n        const meta = document.createElement('div');\r\n        meta.className = 'support-message-meta';\r\n        const sender = document.createElement('span');\r\n        sender.textContent = message.senderDisplayName || options.senderName || ((message.senderRole || options.senderRole) === 'admin' ? 'Hỗ trợ' : 'Bạn');\r\n        const time = document.createElement('span');\r\n        time.textContent = options.pending ? 'Đang gửi' : formatSupportTime(message.createdAt);\r\n        meta.append(sender, time);\r\n\r\n        const body = document.createElement('div');\r\n        body.className = 'support-message-body';\r\n        body.textContent = message.body || options.body || '';\r\n        node.append(meta, body);\r\n\r\n        if (options.pending || options.error) {\r\n            const state = document.createElement('div');\r\n            state.className = 'support-message-state';\r\n            state.textContent = options.error ? (options.errorMessage || 'Gửi lỗi') : 'Đang gửi...';\r\n            node.append(state);\r\n        }\r\n\r\n        if (!pendingNode) {\r\n            supportMessages.append(node);\r\n        }\r\n        setSupportEmptyVisible(false);\r\n        scrollSupportToBottom();\r\n        return node;\r\n    }\r\n\r\n    function formatSupportTime(value) {\r\n        if (!value) return '';\r\n        try {\r\n            return new Intl.DateTimeFormat('vi-VN', {\r\n                hour: '2-digit',\r\n                minute: '2-digit'\r\n            }).format(new Date(value));\r\n        } catch {\r\n            return '';\r\n        }\r\n    }\r\n\r\n    function openSupportChat() {\r\n        post({ type: 'openSupportChat' });\r\n    }\r\n\r\n    function closeSupportChat() {\r\n        if (!supportPopup) return;\r\n        supportPopup.hidden = true;\r\n        supportIsOpen = false;\r\n        post({ type: 'closeSupportChat' });\r\n    }\r\n\r\n    function loadSupportChat(payload) {\r\n        supportConversationId = payload?.conversation?.conversationId || supportConversationId;\r\n        if (supportMessages) {\r\n            supportMessages.textContent = '';\r\n            if (supportEmpty) supportMessages.append(supportEmpty);\r\n        }\r\n        const messages = Array.isArray(payload?.messages) ? payload.messages : [];\r\n        setSupportEmptyVisible(messages.length === 0);\r\n        messages.forEach(message => renderSupportMessage(message));\r\n        setSupportStatus(payload?.conversation?.statusText || 'Đang trực tuyến');\r\n        setSupportBadge(0);\r\n        const lastMessage = messages[messages.length - 1];\r\n        if (lastMessage?.messageId) {\r\n            post({ type: 'markSupportRead', messageId: lastMessage.messageId });\r\n        }\r\n    }\r\n\r\n    function receiveSupportMessage(payload) {\r\n        const message = payload?.message;\r\n        if (!message) return;\r\n        if (payload?.conversation) {\r\n            updateSupportConversation(payload.conversation);\r\n        }\r\n        supportConversationId = message.conversationId || supportConversationId;\r\n        renderSupportMessage(message);\r\n        if (supportIsOpen) {\r\n            post({ type: 'markSupportRead', messageId: message.messageId });\r\n        } else if (message.senderRole === 'admin') {\r\n            const serverUnread = Number(payload?.conversation?.customerUnreadCount);\r\n            setSupportBadge(Number.isFinite(serverUnread) ? serverUnread : supportUnreadCount + 1);\r\n            showToast('Bạn có tin nhắn mới từ NestG Support.');\r\n        }\r\n    }\r\n\r\n    function updateSupportConversation(conversation) {\r\n        if (!conversation) return;\r\n        supportConversationId = conversation.conversationId || supportConversationId;\r\n        if (!supportIsOpen) {\r\n            const serverUnread = Number(conversation.customerUnreadCount);\r\n            setSupportBadge(Number.isFinite(serverUnread) ? serverUnread : supportUnreadCount);\r\n        }\r\n        if (conversation.statusText) {\r\n            setSupportStatus(conversation.statusText);\r\n        }\r\n    }\r\n\r\n    function confirmSupportMessage(clientMessageId, payload) {\r\n        if (payload?.conversation) {\r\n            updateSupportConversation(payload.conversation);\r\n        }\r\n        if (payload?.supportMessage) {\r\n            renderSupportMessage(payload.supportMessage, { clientMessageId });\r\n            setSupportStatus('Đã gửi');\r\n            return;\r\n        }\r\n        const pending = supportMessages?.querySelector(`[data-client-message-id=\"${clientMessageId}\"]`);\r\n        pending?.classList.remove('is-pending');\r\n        setSupportStatus(payload?.message || 'Đã gửi');\r\n    }\r\n\r\n    function failSupportMessage(clientMessageId, message) {\r\n        const pending = supportMessages?.querySelector(`[data-client-message-id=\"${clientMessageId}\"]`);\r\n        if (pending) {\r\n            pending.classList.remove('is-pending');\r\n            pending.classList.add('is-error');\r\n            const state = pending.querySelector('.support-message-state') || document.createElement('div');\r\n            state.className = 'support-message-state';\r\n            state.textContent = message || 'Gửi lỗi';\r\n            if (!state.parentElement) pending.append(state);\r\n            let retry = pending.querySelector('.support-message-retry');\r\n            if (!retry) {\r\n                retry = document.createElement('button');\r\n                retry.type = 'button';\r\n                retry.className = 'support-message-retry';\r\n                retry.textContent = 'Thử lại';\r\n                pending.append(retry);\r\n            }\r\n            retry.onclick = () => {\r\n                const retryBody = pending.querySelector('.support-message-body')?.textContent || '';\r\n                if (!retryBody) return;\r\n                pending.classList.remove('is-error');\r\n                pending.classList.add('is-pending');\r\n                state.textContent = 'Đang gửi...';\r\n                retry.remove();\r\n                post({\r\n                    type: 'sendSupportMessage',\r\n                    body: retryBody,\r\n                    clientMessageId\r\n                });\r\n            };\r\n        }\r\n        setSupportStatus(message || 'Không thể gửi tin nhắn', true);\r\n    }\r\n\r\n    window.__nestgSupport = {\r\n        load: loadSupportChat,\r\n        receiveMessage: receiveSupportMessage,\r\n        updateConversation: updateSupportConversation,\r\n        confirmMessage: confirmSupportMessage,\r\n        failMessage: failSupportMessage,\r\n        setError(message) {\r\n            setSupportStatus(message || 'Không thể kết nối hỗ trợ', true);\r\n        }\r\n    };\r\n\r\n    function closeCartActionPopover() {\r\n        if (cartActionPopover) {\r\n            cartActionPopover.hidden = true;\r\n        }\r\n        activeCartAction = null;\r\n    }\r\n\r\n    function formatQuickWalletPrice(rawPrice, fallbackText) {\r\n        const price = Number(rawPrice || 0);\r\n        if (Number.isFinite(price) && price > 0) {\r\n            return `${new Intl.NumberFormat('vi-VN').format(price)} đ`;\r\n        }\r\n\r\n        return fallbackText || '-';\r\n    }\r\n\r\n    function setQuickWalletConfirmBusy(isBusy) {\r\n        if (quickWalletConfirmSubmit) {\r\n            quickWalletConfirmSubmit.disabled = Boolean(isBusy);\r\n            quickWalletConfirmSubmit.textContent = isBusy ? 'Đang xử lý...' : 'Xác nhận thanh toán';\r\n        }\r\n    }\r\n\r\n    function openQuickWalletConfirm(action) {\r\n        if (!quickWalletConfirm || !action?.gameId) {\r\n            return;\r\n        }\r\n\r\n        pendingQuickWalletAction = action;\r\n        if (quickWalletConfirmTitle) {\r\n            quickWalletConfirmTitle.textContent = action.title || 'Game NestG';\r\n        }\r\n        if (quickWalletConfirmTotal) {\r\n            quickWalletConfirmTotal.textContent = formatQuickWalletPrice(action.price, action.priceText);\r\n        }\r\n        setQuickWalletConfirmBusy(false);\r\n        quickWalletConfirm.hidden = false;\r\n    }\r\n\r\n    function closeQuickWalletConfirm() {\r\n        if (quickWalletConfirm) {\r\n            quickWalletConfirm.hidden = true;\r\n        }\r\n        setQuickWalletConfirmBusy(false);\r\n        pendingQuickWalletAction = null;\r\n    }\r\n\r\n    function openCartActionPopover(button) {\r\n        if (!cartActionPopover || !button) {\r\n            return;\r\n        }\r\n\r\n        const card = button.closest('[data-card]');\r\n        const gameId = button.getAttribute('data-game-id') || card?.getAttribute('data-game-id') || '';\r\n        const versionId = button.getAttribute('data-version-id') || card?.getAttribute('data-version-id') || '';\r\n        if (!gameId) {\r\n            return;\r\n        }\r\n\r\n        const title = card?.querySelector('h3')?.textContent?.trim() || 'Game';\r\n        const price = card?.getAttribute('data-price') || '';\r\n        const priceText = card?.querySelector('.price-stack strong')?.textContent?.trim() || '';\r\n        activeCartAction = { button, card, gameId, versionId, title, price, priceText };\r\n        if (cartActionTitle) {\r\n            cartActionTitle.textContent = title;\r\n        }\r\n\r\n        cartActionPopover.hidden = false;\r\n        const buttonRect = button.getBoundingClientRect();\r\n        const popoverRect = cartActionPopover.getBoundingClientRect();\r\n        const viewportPadding = 12;\r\n        const left = Math.min(\r\n            Math.max(viewportPadding, buttonRect.right - popoverRect.width),\r\n            window.innerWidth - popoverRect.width - viewportPadding);\r\n        const belowTop = buttonRect.bottom + 10;\r\n        const aboveTop = buttonRect.top - popoverRect.height - 10;\r\n        const top = belowTop + popoverRect.height + viewportPadding <= window.innerHeight\r\n            ? belowTop\r\n            : Math.max(viewportPadding, aboveTop);\r\n\r\n        cartActionPopover.style.left = `${left}px`;\r\n        cartActionPopover.style.top = `${top}px`;\r\n    }\r\n\r\n    function animateCartFly(sourceButton) {\r\n        if (!sourceButton || !cartPill) {\r\n            return;\r\n        }\r\n\r\n        const card = sourceButton.closest('[data-card]');\r\n        const image = card?.querySelector('.catalog-media img');\r\n        const source = image || sourceButton;\r\n        const sourceRect = source.getBoundingClientRect();\r\n        const targetRect = cartPill.getBoundingClientRect();\r\n        if (!sourceRect.width || !sourceRect.height || !targetRect.width || !targetRect.height) {\r\n            return;\r\n        }\r\n\r\n        const flyer = document.createElement('div');\r\n        flyer.className = 'cart-flyer';\r\n        flyer.style.left = `${sourceRect.left}px`;\r\n        flyer.style.top = `${sourceRect.top}px`;\r\n        flyer.style.width = `${Math.min(sourceRect.width, 88)}px`;\r\n        flyer.style.height = `${Math.min(sourceRect.height, 62)}px`;\r\n\r\n        if (image?.currentSrc || image?.src) {\r\n            const cloneImage = document.createElement('img');\r\n            cloneImage.src = image.currentSrc || image.src;\r\n            cloneImage.alt = '';\r\n            flyer.append(cloneImage);\r\n        }\r\n\r\n        document.body.append(flyer);\r\n        const flyerRect = flyer.getBoundingClientRect();\r\n        const startX = sourceRect.left + sourceRect.width / 2 - (flyerRect.left + flyerRect.width / 2);\r\n        const startY = sourceRect.top + sourceRect.height / 2 - (flyerRect.top + flyerRect.height / 2);\r\n        const endX = targetRect.left + targetRect.width / 2 - (flyerRect.left + flyerRect.width / 2);\r\n        const endY = targetRect.top + targetRect.height / 2 - (flyerRect.top + flyerRect.height / 2);\r\n\r\n        flyer.animate([\r\n            { transform: `translate(${startX}px, ${startY}px) scale(1)`, opacity: .96 },\r\n            { transform: `translate(${(startX + endX) / 2}px, ${Math.min(startY, endY) - 52}px) scale(.72)`, opacity: .86, offset: .62 },\r\n            { transform: `translate(${endX}px, ${endY}px) scale(.18)`, opacity: 0 }\r\n        ], {\r\n            duration: 620,\r\n            easing: 'cubic-bezier(.2,.72,.18,1)',\r\n            fill: 'forwards'\r\n        }).finished.finally(() => flyer.remove());\r\n    }\r\n\r\n    function setAccountMenuOpen(isOpen) {\r\n        if (!accountToggle || !accountMenu) {\r\n            return;\r\n        }\r\n\r\n        accountMenu.hidden = !isOpen;\r\n        accountToggle.classList.toggle('is-open', isOpen);\r\n        accountToggle.setAttribute('aria-expanded', String(isOpen));\r\n\r\n        if (isOpen) {\r\n            accountMenu.querySelector('[role=\"menuitem\"]')?.focus({ preventScroll: true });\r\n        }\r\n    }\r\n\r\n    function parseWalletAmount(value) {\r\n        const digits = String(value || '').replace(/\\D/g, '');\r\n        return digits ? Number(digits) : 0;\r\n    }\r\n\r\n    function setWalletStep(step) {\r\n        walletSteps.forEach(element => {\r\n            element.hidden = element.getAttribute('data-wallet-step') !== step;\r\n        });\r\n    }\r\n\r\n    function setWalletStatus(message = '', isError = false) {\r\n        if (!walletStatus) return;\r\n        walletStatus.textContent = message;\r\n        walletStatus.classList.toggle('is-error', Boolean(isError));\r\n    }\r\n\r\n    function setWalletBusy(isBusy, message = '', isError = false) {\r\n        if (walletGenerateButton) {\r\n            walletGenerateButton.disabled = isBusy;\r\n            walletGenerateButton.textContent = isBusy ? 'Đang tạo mã...' : 'Tạo mã thanh toán';\r\n        }\r\n        if (walletAmountInput) walletAmountInput.disabled = isBusy;\r\n        walletQuickGrid?.querySelectorAll('button').forEach(button => button.disabled = isBusy);\r\n        setWalletStatus(message, isError);\r\n    }\r\n\r\n    function setWalletBalance(value) {\r\n        document.querySelectorAll('[data-wallet-balance], [data-wallet-current-balance]').forEach(element => {\r\n            element.textContent = value || '0 đ';\r\n        });\r\n    }\r\n\r\n    function openWalletModal(payload) {\r\n        if (!walletModal) return;\r\n        window.clearInterval(walletPollTimer);\r\n        activeWalletOrderCode = '';\r\n        