   }\r\n\r\n        if (target.closest('[data-order-checkout-refresh]')) {\r\n            if (!activeOrderCheckoutCode) return;\r\n            if (orderCheckoutRefresh) {\r\n                orderCheckoutRefresh.disabled = true;\r\n                orderCheckoutRefresh.textContent = 'Đang kiểm tra...';\r\n            }\r\n            post({ type: 'refreshOrderCheckoutStatus', orderCode: activeOrderCheckoutCode });\r\n            return;\r\n        }\r\n\r\n        if (target.closest('[data-order-checkout-wallet]')) {\r\n            openOrderWalletConfirm();\r\n            return;\r\n        }\r\n\r\n        if (target.closest('[data-order-wallet-confirm-cancel]')) {\r\n            closeOrderWalletConfirm();\r\n            return;\r\n        }\r\n\r\n        if (target.closest('[data-order-wallet-confirm-submit]')) {\r\n            if (activeOrderCheckoutCode) {\r\n                setOrderWalletConfirmBusy(true);\r\n                closeOrderWalletConfirm();\r\n                post({ type: 'payOrderCheckoutWithWallet', orderCode: activeOrderCheckoutCode });\r\n            }\r\n            return;\r\n        }\r\n\r\n        if (target.closest('[data-order-checkout-confirm]')) {\r\n            closeOrderCheckoutPopup(true);\r\n            return;\r\n        }\r\n\r\n        const miniCartButton = target.closest('.mini-cart[data-host-action=\"addToCart\"]');\r\n        if (miniCartButton) {\r\n            event.preventDefault();\r\n            event.stopPropagation();\r\n            setAccountMenuOpen(false);\r\n            openCartActionPopover(miniCartButton);\r\n            return;\r\n        }\r\n\r\n        if (cartActionPopover && !cartActionPopover.hidden && !target.closest('[data-cart-action-popover]')) {\r\n            closeCartActionPopover();\r\n        }\r\n\r\n        if (target.closest('[data-account-toggle]')) {\r\n            event.preventDefault();\r\n            event.stopPropagation();\r\n            setAccountMenuOpen(Boolean(accountMenu?.hidden));\r\n            closeFilterPanels();\r\n            return;\r\n        }\r\n\r\n        if (!target.closest('[data-account-menu]')) {\r\n            setAccountMenuOpen(false);\r\n        }\r\n\r\n        const filterToggle = target.closest('[data-filter-toggle]');\r\n        if (filterToggle) {\r\n            const panelName = filterToggle.getAttribute('data-filter-toggle');\r\n            toggleFilterPanel(panelName);\r\n            return;\r\n        }\r\n\r\n        const genreButton = target.closest('[data-genre-filter]');\r\n        if (genreButton) {\r\n            setActiveGenre(\r\n                genreButton.getAttribute('data-genre-filter') || 'all',\r\n                genreButton.textContent || 'Thể loại');\r\n            closeFilterPanels();\r\n            applyFilters();\r\n            return;\r\n        }\r\n\r\n        const categoryButton = target.closest('[data-category-filter]');\r\n        if (categoryButton) {\r\n            setActiveCategory(\r\n                categoryButton.getAttribute('data-category-filter') || 'all',\r\n                categoryButton.textContent || 'Danh mục');\r\n            closeFilterPanels();\r\n            applyFilters();\r\n            return;\r\n        }\r\n\r\n        const sortButton = target.closest('[data-sort-order]');\r\n        if (sortButton) {\r\n            setSortOrder(sortButton.getAttribute('data-sort-order') || 'default');\r\n            closeFilterPanels();\r\n            applyFilters();\r\n            return;\r\n        }\r\n\r\n        if (!target.closest('[data-filter-panel]')) {\r\n            closeFilterPanels();\r\n        }\r\n\r\n        const railNav = target.closest('[data-rail-nav]');\r\n        if (railNav) {\r\n            const railName = railNav.getAttribute('data-rail-nav');\r\n            const direction = Number(railNav.getAttribute('data-direction') || '1');\r\n            const rail = document.querySelector(`[data-rail=\"${railName}\"]`);\r\n            if (rail) {\r\n                rail.dispatchEvent(new Event('nestg:pause-auto-rail'));\r\n                const loopWidth = Number(rail.dataset.loopWidth || 0);\r\n                if (direction < 0 && rail.dataset.autoLoopRail === 'true' && loopWidth > 0 && rail.scrollLeft <= 2) {\r\n                    rail.scrollLeft = loopWidth;\r\n                }\r\n                rail.scrollBy({ left: direction * Math.max(260, rail.clientWidth * .82), behavior: 'smooth' });\r\n            }\r\n            return;\r\n        }\r\n\r\n        const hostAction = target.closest('[data-host-action]');\r\n        if (!hostAction) {\r\n            return;\r\n        }\r\n\r\n        event.preventDefault();\r\n        event.stopPropagation();\r\n\r\n        const action = hostAction.getAttribute('data-host-action');\r\n        setAccountMenuOpen(false);\r\n        if (action === 'openWalletTopupModal') {\r\n            post({ type: action });\r\n            return;\r\n        }\r\n        if (action === 'home') {\r\n            window.scrollTo({ top: 0, behavior: 'smooth' });\r\n            return;\r\n        }\r\n        if (action === 'support') {\r\n            openSupportChat();\r\n            return;\r\n        }\r\n\r\n        if (action === 'wishlist' || action === 'addGame') {\r\n            showToast('Tính năng đang cập nhật');\r\n            return;\r\n        }\r\n\r\n        const gameId = hostAction.getAttribute('data-game-id');\r\n        const versionId = hostAction.getAttribute('data-version-id');\r\n        const comboId = hostAction.getAttribute('data-combo-id');\r\n        if (action === 'openGame') {\r\n            lastOpenedGameId = gameId || '';\r\n        }\r\n        post({ type: action, gameId, versionId, comboId });\r\n    });\r\n\r\n    document.addEventListener('keydown', event => {\r\n        const openedModal = getActiveModal();\r\n        if (event.key === 'Tab' && openedModal) {\r\n            const focusables = getModalFocusables(openedModal);\r\n            if (focusables.length > 0) {\r\n                const first = focusables[0];\r\n                const last = focusables[focusables.length - 1];\r\n                if (event.shiftKey && document.activeElement === first) {\r\n                    event.preventDefault();\r\n                    last.focus();\r\n                } else if (!event.shiftKey && document.activeElement === last) {\r\n                    event.preventDefault();\r\n                    first.focus();\r\n                }\r\n            }\r\n            return;\r\n        }\r\n\r\n        const keyboardCard = event.target instanceof Element\r\n            ? event.target.closest('[role=\"button\"][data-host-action]')\r\n            : null;\r\n        if (keyboardCard && (event.key === 'Enter' || event.key === ' ')) {\r\n            event.preventDefault();\r\n            keyboardCard.click();\r\n            return;\r\n        }\r\n\r\n        if (event.key === 'Escape') {\r\n            if (launcherUpdateModal && !launcherUpdateModal.hidden && !isLauncherUpdateForce() && !launcherUpdateBusy) {\r\n                hideLauncherUpdate(true);\r\n                return;\r\n            }\r\n            if (quickWalletConfirm && !quickWalletConfirm.hidden) {\r\n                closeQuickWalletConfirm();\r\n                return;\r\n            }\r\n            if (cartActionPopover && !cartActionPopover.hidden) {\r\n                closeCartActionPopover();\r\n                return;\r\n            }\r\n            if (orderCheckoutModal && !orderCheckoutModal.hidden) {\r\n                closeOrderCheckoutPopup(false);\r\n                return;\r\n            }\r\n            if (walletModal && !walletModal.hidden) {\r\n                closeWalletModal();\r\n                return;\r\n            }\r\n            if (supportPopup && !supportPopup.hidden) {\r\n                closeSupportChat();\r\n                return;\r\n            }\r\n            setAccountMenuOpen(false);\r\n        }\r\n    });\r\n\r\n    supportClose?.addEventListener('click', closeSupportChat);\r\n\r\n    supportForm?.addEventListener('submit', event => {\r\n        event.preventDefault();\r\n        const body = supportInput?.value.trim() || '';\r\n        if (!body) {\r\n            setSupportStatus('Nhập nội dung trước khi gửi.', true);\r\n            supportInput?.focus();\r\n            return;\r\n        }\r\n\r\n        const clientMessageId = createSupportClientId();\r\n        renderSupportMessage(\r\n            {\r\n                body,\r\n                clientMessageId,\r\n                senderRole: 'customer',\r\n                senderDisplayName: 'Bạn',\r\n                createdAt: new Date().toISOString()\r\n            },\r\n            {\r\n                pending: true,\r\n                clientMessageId,\r\n                body,\r\n                senderRole: 'customer',\r\n                senderName: 'Bạn'\r\n            });\r\n        if (supportInput) {\r\n            supportInput.value = '';\r\n        }\r\n        setSupportStatus('Đang gửi...');\r\n        post({\r\n            type: 'sendSupportMessage',\r\n            body,\r\n            clientMessageId\r\n        });\r\n    });\r\n\r\n    walletAmountInput?.addEventListener('input', () => {\r\n        const amount = parseWalletAmount(walletAmountInput.value);\r\n        walletAmountInput.value = amount ? new Intl.NumberFormat('vi-VN').format(amount) : '';\r\n        walletQuickGrid?.querySelectorAll('button').forEach(button => {\r\n            button.classList.toggle(\r\n                'is-selected',\r\n                Number(button.getAttribute('data-wallet-quick') || 0) === amount);\r\n        });\r\n        setWalletStatus('');\r\n    });\r\n\r\n    function normalize(value) {\r\n        return String(value || '').trim().toLowerCase().replace(/đ/g, 'd').normalize('NFD').replace(/[\\u0300-\\u036f]/g, '');\r\n    }\r\n\r\n    function closeFilterPanels() {\r\n        if (genrePanel) {\r\n            genrePanel.hidden = true;\r\n        }\r\n        if (genreToggle) {\r\n            genreToggle.classList.remove('is-open');\r\n            genreToggle.setAttribute('aria-expanded', 'false');\r\n        }\r\n        if (categoryPanel) {\r\n            categoryPanel.hidden = true;\r\n        }\r\n        if (categoryToggle) {\r\n            categoryToggle.classList.remove('is-open');\r\n            categoryToggle.setAttribute('aria-expanded', 'false');\r\n        }\r\n        if (pricePanel) {\r\n            pricePanel.hidden = true;\r\n        }\r\n        if (priceToggle) {\r\n            priceToggle.classList.remove('is-open');\r\n            priceToggle.setAttribute('aria-expanded', 'false');\r\n        }\r\n    }\r\n\r\n    function toggleFilterPanel(panelName) {\r\n        const panelMap = {\r\n            genres: { panel: genrePanel, toggle: genreToggle, input: tagSearchInput },\r\n            categories: { panel: categoryPanel, toggle: categoryToggle, input: categorySearchInput },\r\n            price: { panel: pricePanel, toggle: priceToggle, input: null }\r\n        };\r\n        const config = panelMap[panelName];\r\n        if (!config?.panel || !config?.toggle) {\r\n            return;\r\n        }\r\n\r\n        const shouldOpen = config.panel.hidden;\r\n        closeFilterPanels();\r\n        config.panel.hidden = !shouldOpen;\r\n        config.toggle.classList.toggle('is-open', shouldOpen);\r\n        config.toggle.setAttribute('aria-expanded', String(shouldOpen));\r\n        if (shouldOpen && panelName === 'price') {\r\n            initializePriceFilter(true);\r\n        }\r\n        if (shouldOpen && config.input) {\r\n            config.input.focus({ preventScroll: true });\r\n            config.input.select();\r\n        }\r\n    }\r\n\r\n    function setActiveGenre(value, label) {\r\n        activeGenre = value || 'all';\r\n        const isAll = activeGenre === 'all';\r\n        if (activeGenreLabel) {\r\n            activeGenreLabel.textContent = isAll ? 'Thể loại' : String(label || activeGenre).trim();\r\n        }\r\n\r\n        document.querySelectorAll('[data-genre-filter]').forEach(button => {\r\n            button.classList.toggle('is-selected', button.getAttribute('data-genre-filter') === activeGenre);\r\n        });\r\n    }\r\n\r\n    function filterGenreOptions() {\r\n        const query = normalize(tagSearchInput?.value);\r\n        document.querySelectorAll('[data-genre-filter]').forEach(button => {\r\n            const value = button.getAttribute('data-genre-filter') || '';\r\n            const label = normalize(button.textContent);\r\n            button.hidden = value !== 'all' && Boolean(query) && !label.includes(query);\r\n        });\r\n    }\r\n\r\n    function setActiveCategory(value, label) {\r\n        activeCategory = value || 'all';\r\n        const isAll = activeCategory === 'all';\r\n        if (activeCategoryLabel) {\r\n            activeCategoryLabel.textContent = isAll ? 'Danh mục' : String(label || activeCategory).trim();\r\n        }\r\n\r\n        document.querySelectorAll('[data-category-filter]').forEach(button => {\r\n            button.classList.toggle('is-selected', button.getAttribute('data-category-filter') === activeCategory);\r\n        });\r\n    }\r\n\r\n    function filterCategoryOptions() {\r\n        const query = normalize(categorySearchInput?.value);\r\n        document.querySelectorAll('[data-category-filter]').forEach(button => {\r\n            const value = button.getAttribute('data-category-filter') || '';\r\n            const label = normalize(button.textContent);\r\n            button.hidden = value !== 'all' && Boolean(query) && !label.includes(query);\r\n        });\r\n    }\r\n\r\n    function setSortOrder(value) {\r\n        sortOrder = value || 'default';\r\n        document.querySelectorAll('[data-sort-order]').forEach(button => {\r\n            button.classList.toggle('is-selected', button.getAttribute('data-sort-order') === sortOrder);\r\n        });\r\n    }\r\n\r\n    function containsTag(tagList, tag) {\r\n        const normalizedTag = normalize(tag);\r\n        if (!normalizedTag) {\r\n            return false;\r\n        }\r\n\r\n        return String(tagList || '')\r\n            .split('|')\r\n            .map(normalize)\r\n            .some(item => item === normalizedTag);\r\n    }\r\n\r\n    function getCatalogCards() {\r\n        return catalogGrid\r\n            ? Array.from(catalogGrid.querySelectorAll('[data-card]'))\r\n            : [];\r\n    }\r\n\r\n    function getCardPrice(card) {\r\n        const parsed = Number(card.getAttribute('data-price') || '');\r\n        return Number.isFinite(parsed) && parsed >= 0 ? parsed : null;\r\n    }\r\n\r\n    function getPriceStep(maxPrice) {\r\n        if (maxPrice <= 500000) {\r\n            return 10000;\r\n        }\r\n\r\n        if (maxPrice <= 2000000) {\r\n            return 50000;\r\n        }\r\n\r\n        return 100000;\r\n    }\r\n\r\n    function initializePriceFilter(preserveValue = false) {\r\n        if (!priceRangeInput) {\r\n            return;\r\n        }\r\n\r\n        const prices = getCatalogCards()\r\n            .map(getCardPrice)\r\n            .filter(price => price !== null);\r\n        const detectedMaximum = Math.max(Number(document.body.dataset.catalogMaximumPrice || 0),\r\n            prices.length > 0 ? Math.max(...prices) : 0);\r\n        const step = getPriceStep(detectedMaximum);\r\n        const previousValue = Number(priceRangeInput.value);\r\n\r\n        maximumPrice = Math.max(step, Math.ceil(detectedMaximum / step) * step);\r\n        selectedMaximumPrice = preserveValue && Number.isFinite(previousValue)\r\n            ? Math.min(previousValue, maximumPrice)\r\n            : maximumPrice;\r\n\r\n        priceRangeInput.min = '0';\r\n        priceRangeInput.max = String(maximumPrice);\r\n        priceRangeInput.step = String(step);\r\n        priceRangeInput.value = String(selectedMaximumPrice);\r\n\r\n        if (priceMaximumLabel) {\r\n            priceMaximumLabel.textContent = currencyFormatter.format(maximumPrice);\r\n        }\r\n        updatePriceLabels();\r\n    }\r\n\r\n    function updatePriceLabels() {\r\n        if (!priceRangeInput) {\r\n            return;\r\n        }\r\n\r\n        const isAllPrices = selectedMaximumPrice >= maximumPrice;\r\n        const progress = maximumPrice > 0\r\n            ? Math.min(100, Math.max(0, selectedMaximumPrice / maximumPrice * 100))\r\n            : 100;\r\n        priceRangeInput.style.setProperty('--price-progress', `${progress}%`);\r\n\r\n        if (priceValueLabel) {\r\n            priceValueLabel.textContent = isAllPrices\r\n                ? 'Tất cả'\r\n                : currencyFormatter.format(selectedMaximumPrice);\r\n        }\r\n        if (activePriceLabel) {\r\n            activePriceLabel.textContent = isAllPrices && sortOrder === 'default'\r\n                ? 'Giá & Sắp xếp'\r\n                : isAllPrices\r\n                    ? 'Sắp xếp'\r\n                    : `Đến ${currencyFormatter.format(selectedMaximumPrice)}`;\r\n        }\r\n        priceToggle?.classList.toggle('is-active', !isAllPrices || sortOrder !== 'default');\r\n    }\r\n\r\n    function sortCatalogCards() {\r\n        if (!catalogGrid) {\r\n            return;\r\n        }\r\n\r\n        const cards = getCatalogCards();\r\n        cards.forEach((card, index) => {\r\n            if (!card.hasAttribute('data-original-index')) {\r\n                card.setAttribute('data-original-index', String(index));\r\n            }\r\n        });\r\n\r\n        const sortedCards = [...cards].sort((left, right) => {\r\n            if (sortOrder === 'price-asc' || sortOrder === 'price-desc') {\r\n                const leftPrice = getCardPrice(left) ?? Number.MAX_SAFE_INTEGER;\r\n                const rightPrice = getCardPrice(right) ?? Number.MAX_SAFE_INTEGER;\r\n                return sortOrder === 'price-asc'\r\n                    ? leftPrice - rightPrice\r\n                    : rightPrice - leftPrice;\r\n            }\r\n\r\n            if (sortOrder === 'title') {\r\n                return String(left.getAttribute('data-title') || '').localeCompare(\r\n                    String(right.getAttribute('data-title') || ''),\r\n                    'vi',\r\n                    { sensitivity: 'base' });\r\n            }\r\n\r\n            return Number(left.getAttribute('data-original-index') || 0) -\r\n                Number(right.getAttribute('data-original-index') || 0);\r\n        });\r\n\r\n        sortedCards.forEach(card => catalogGrid.append(card));\r\n    }\r\n\r\n    function applyFilters() {\r\n        if (catalogGrid && !restoringCatalog) {\r\n            const key = JSON.stringify(getCatalogQuery());\r\n            if (catalogQueryKey && key !== catalogQueryKey) {\r\n                catalogQueryKey = key;\r\n                catalogGeneration += 1;\r\n                catalogHasMore = true;\r\n                catalogNextPage = 1;\r\n                catalogGrid.replaceChildren();\r\n                renderedCatalogIds.clear();\r\n                requestCatalogPage(1, true);\r\n            } else if (!catalogQueryKey) catalogQueryKey = key;\r\n        }\r\n        const query = normalize(searchInput?.value);\r\n        const cards = Array.from(document.querySelectorAll('[data-card], .sale-rail-card, .wide-card'));\r\n        let shownCatalog = 0;\r\n\r\n        cards.forEach(card => {\r\n            const haystack = normalize(card.getAttribute('data-search'));\r\n            const category = normalize(card.getAttribute('data-category'));\r\n            const tags = card.getAttribute('data-tags') || '';\r\n            const matchesQuery = !query || haystack.includes(query);\r\n            const matchesGenre = activeGenre === 'all' ||\r\n                category === normalize(activeGenre) ||\r\n                containsTag(tags, activeGenre);\r\n            const matchesCategory = activeCategory === 'all' ||\r\n                category === normalize(activeCategory);\r\n            const price = getCardPrice(card);\r\n            const matchesPrice = !card.matches('[data-card]') ||\r\n                selectedMaximumPrice >= maximumPrice ||\r\n                price === null ||\r\n                price <= selectedMaximumPrice;\r\n            // Catalog cards were filtered and ordered across the full snapshot by\r\n            // the API. Filtering them again by their first category loses games.\r\n            const visible = card.matches('[data-card]') || (matchesQuery && matchesGenre && matchesCategory && matchesPrice);\r\n            card.hidden = !visible;\r\n            if (visible && card.matches('[data-card]')) {\r\n                shownCatalog += 1;\r\n            }\r\n        });\r\n\r\n        updatePriceLabels();\r\n\r\n        if (visibleCount) {\r\n            visibleCount.textContent = isLoadingCatalogPage && catalogNextPage === 1\r\n                ? 'Đang tìm...' : `${shownCatalog} / ${catalogTotalCount} game`;\r\n        }\r\n        if (priceResultLabel) {\r\n            priceResultLabel.textContent = shownCatalog > 0\r\n                ? `Đang hiển thị ${shownCatalog} game phù hợp.`\r\n                : catalogRetryPage\r\n                    ? 'Chưa tải được danh sách. Bạn có thể thử lại.'\r\n                : isLoadingCatalogPage\r\n                    ? 'Đang tìm game phù hợp...'\r\n                : 'Không có game phù hợp với mức giá này.';\r\n        }\r\n        if (emptyState) {\r\n            emptyState.hidden = shownCatalog !== 0 || isLoadingCatalogPage || restoringCatalog || Boolean(catalogRetryPage);\r\n        }\r\n        refreshAutoRailLoops();\r\n\r\n        setCatalogLoading(isLoadingCatalogPage);\r\n\r\n    }\r\n\r\n    if (searchInput) {\r\n        searchInput.addEventListener('input', () => {\r\n            window.clearTimeout(searchTimer);\r\n            searchTimer = window.setTimeout(applyFilters, 300);\r\n        });\r\n    }\r\n\r\n    if (tagSearchInput) {\r\n        tagSearchInput.addEventListener('input', filterGenreOptions);\r\n        tagSearchInput.addEventListener('keydown', event => {\r\n            if (event.key === 'Escape') {\r\n                closeFilterPanels();\r\n                genreToggle?.focus();\r\n            }\r\n        });\r\n    }\r\n\r\n    if (categorySearchInput) {\r\n        categorySearchInput.addEventListener('input', filterCategoryOptions);\r\n        categorySearchInput.addEventListener('keydown', event => {\r\n            if (event.key === 'Escape') {\r\n                closeFilterPanels();\r\n                categoryToggle?.focus();\r\n            }\r\n        });\r\n    }\r\n\r\n    if (priceRangeInput) {\r\n        priceRangeInput.addEventListener('input', () => {\r\n            selectedMaximumPrice = Number(priceRangeInput.value);\r\n            updatePriceLabels();\r\n            window.clearTimeout(searchTimer);\r\n            searchTimer = window.setTimeout(applyFilters, 300);\r\n        });\r\n    }\r\n\r\n    priceResetButton?.addEventListener('click', () => {\r\n        selectedMaximumPrice = maximumPrice;\r\n        if (priceRangeInput) {\r\n            priceRangeInput.value = String(maximumPrice);\r\n        }\r\n        setSortOrder('default');\r\n        applyFilters();\r\n    });\r\n\r\n    document.addEventListener('keydown', event => {\r\n        if (event.key === 'Escape') {\r\n            closeFilterPanels();\r\n        }\r\n    });\r\n\r\n    window.addEventListener('scroll', checkCatalogScrollPosition, { passive: true });\r\n    window.addEventListener('resize', () => window.setTimeout(checkCatalogScrollPosition, 120));\r\n\r\n    function updateCountdowns() {\r\n        const now = Date.now();\r\n        document.querySelectorAll('[data-countdown]').forEach(element => {\r\n            const target = Number(element.getAttribute('data-countdown') || 0);\r\n            const delta = Math.max(0, target - now);\r\n            const days = Math.floor(delta / 86400000);\r\n            const hours = Math.floor((delta % 86400000) / 3600000);\r\n            const minutes = Math.floor((delta % 3600000) / 60000);\r\n            const seconds = Math.floor((delta % 60000) / 1000);\r\n            element.textContent = `${days} ngày ${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;\r\n        });\r\n    }\r\n\r\n    initializePriceFilter(false);\r\n    setSortOrder('default');\r\n    applyFilters();\r\n    window.setTimeout(checkCatalogScrollPosition, 250);\r\n    updateCountdowns();\r\n    window.setInterval(updateCountdowns, 1000);\r\n    setupAutoRailLoop(saleRail);\r\n})();";
	}
